const getPurchasesOverview = `-- name: GetPurchasesOverview :one
SELECT (
        SELECT COALESCE(SUM((poi.quantity - poi.received_quantity) * poi.unit_cost), 0)
        FROM purchase_order_items poi
            INNER JOIN purchase_orders po ON po.id = poi.order_id
        WHERE po.company_id = $1
            AND po.status IN ('sent', 'partial')
    )::FLOAT AS pending_total,
    (
        SELECT COALESCE(SUM(pr.total), 0)
        FROM purchase_receipts pr
        WHERE pr.company_id = $1
            AND pr.status = 'active'
            AND pr.received_at >= $2::TIMESTAMPTZ
    )::FLOAT AS received_this_month,
    (
        SELECT COUNT(*)
        FROM purchase_orders po
        WHERE po.company_id = $1
            AND po.status IN ('sent', 'partial')
            AND po.expected_date < $3::DATE
    )::INT AS late_orders
`

type GetPurchasesOverviewParams struct {
	CompanyID  pgtype.UUID        `json:"company_id"`
	MonthStart pgtype.Timestamptz `json:"month_start"`
	Today      pgtype.Date        `json:"today"`
}

type GetPurchasesOverviewRow struct {
	PendingTotal      float64 `json:"pending_total"`
	ReceivedThisMonth float64 `json:"received_this_month"`
	LateOrders        int32   `json:"late_orders"`
}

// Indicadores da tela de compras: o que está a caminho e o que entrou no mês
func (q *Queries) GetPurchasesOverview(ctx context.Context, arg GetPurchasesOverviewParams) (GetPurchasesOverviewRow, error) {
	row := q.db.QueryRow(ctx, getPurchasesOverview, arg.CompanyID, arg.MonthStart, arg.Today)
	var i GetPurchasesOverviewRow
	err := row.Scan(&i.PendingTotal, &i.ReceivedThisMonth, &i.LateOrders)
	return i, err
}

