const searchPurchaseModels = `-- name: SearchPurchaseModels :many
SELECT MIN(p.model_name)::TEXT AS model_name,
    COUNT(*)::INT AS variations
FROM products p
WHERE p.company_id = $1
    AND p.deleted_at IS NULL
    AND p.model_name IS NOT NULL
    AND p.model_name ILIKE '%' || $2::TEXT || '%'
GROUP BY lower(p.model_name)
HAVING COUNT(*) > 1
ORDER BY 1
LIMIT 5
`

type SearchPurchaseModelsParams struct {
	CompanyID pgtype.UUID `json:"company_id"`
	Search    string      `json:"search"`
}

type SearchPurchaseModelsRow struct {
	ModelName  string `json:"model_name"`
	Variations int32  `json:"variations"`
}

// Modelos com mais de uma variação que casam com a busca (atalho de recompra)
func (q *Queries) SearchPurchaseModels(ctx context.Context, arg SearchPurchaseModelsParams) ([]SearchPurchaseModelsRow, error) {
	rows, err := q.db.Query(ctx, searchPurchaseModels, arg.CompanyID, arg.Search)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []SearchPurchaseModelsRow{}
	for rows.Next() {
		var i SearchPurchaseModelsRow
		if err := rows.Scan(&i.ModelName, &i.Variations); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const searchPurchaseProducts = `-- name: SearchPurchaseProducts :many
SELECT p.id,
    p.name::TEXT AS name,
    COALESCE(p.model_name, '')::TEXT AS model_name,
    COALESCE(p.color, '')::TEXT AS color,
    COALESCE(p.size, '')::TEXT AS size,
    COALESCE(p.barcode, '')::TEXT AS barcode,
    p.unit::TEXT AS unit,
    p.sell_in_bulk,
    COALESCE(p.quantity, 0)::INT AS quantity,
    COALESCE(p.cost_price, 0)::FLOAT AS cost_price,
    COALESCE(p.sale_price, 0)::FLOAT AS sale_price,
    COUNT(*) OVER()::INT AS total_rows
FROM products p
WHERE p.company_id = $1
    AND p.deleted_at IS NULL
    AND (
        $2::TEXT = ''
        OR p.name ILIKE '%' || $2::TEXT || '%'
        OR p.barcode = $2::TEXT
    )
ORDER BY p.name
LIMIT $4 OFFSET $3
`

type SearchPurchaseProductsParams struct {
	CompanyID  pgtype.UUID `json:"company_id"`
	Search     string      `json:"search"`
	PageOffset int32       `json:"page_offset"`
	PageLimit  int32       `json:"page_limit"`
}

type SearchPurchaseProductsRow struct {
	ID         pgtype.UUID `json:"id"`
	Name       string      `json:"name"`
	ModelName  string      `json:"model_name"`
	Color      string      `json:"color"`
	Size       string      `json:"size"`
	Barcode    string      `json:"barcode"`
	Unit       string      `json:"unit"`
	SellInBulk bool        `json:"sell_in_bulk"`
	Quantity   int32       `json:"quantity"`
	CostPrice  float64     `json:"cost_price"`
	SalePrice  float64     `json:"sale_price"`
	TotalRows  int32       `json:"total_rows"`
}

// Busca de produtos para o pedido (Compras não depende do módulo Estoque)
func (q *Queries) SearchPurchaseProducts(ctx context.Context, arg SearchPurchaseProductsParams) ([]SearchPurchaseProductsRow, error) {
	rows, err := q.db.Query(ctx, searchPurchaseProducts,
		arg.CompanyID,
		arg.Search,
		arg.PageOffset,
		arg.PageLimit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []SearchPurchaseProductsRow{}
	for rows.Next() {
		var i SearchPurchaseProductsRow
		if err := rows.Scan(
			&i.ID,
			&i.Name,
			&i.ModelName,
			&i.Color,
			&i.Size,
			&i.Barcode,
			&i.Unit,
			&i.SellInBulk,
			&i.Quantity,
			&i.CostPrice,
			&i.SalePrice,
			&i.TotalRows,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const updatePurchaseOrderHeader = `-- name: UpdatePurchaseOrderHeader :exec
UPDATE purchase_orders
SET vendor_id = $1,
    expected_date = $2,
    notes = $3,
    updated_at = NOW()
WHERE id = $4
`

type UpdatePurchaseOrderHeaderParams struct {
	VendorID     pgtype.UUID `json:"vendor_id"`
	ExpectedDate pgtype.Date `json:"expected_date"`
	Notes        pgtype.Text `json:"notes"`
	ID           pgtype.UUID `json:"id"`
}

func (q *Queries) UpdatePurchaseOrderHeader(ctx context.Context, arg UpdatePurchaseOrderHeaderParams) error {
	_, err := q.db.Exec(ctx, updatePurchaseOrderHeader,
		arg.VendorID,
		arg.ExpectedDate,
		arg.Notes,
		arg.ID,
	)
	return err
}

const updatePurchaseOrderStatus = `-- name: UpdatePurchaseOrderStatus :exec
UPDATE purchase_orders
SET status = $1,
    sent_at = CASE
        WHEN sent_at IS NULL AND $1::purchase_order_status <> 'draft' THEN NOW()
        ELSE sent_at
    END,
    updated_at = NOW()
WHERE id = $2
`

type UpdatePurchaseOrderStatusParams struct {
	Status PurchaseOrderStatus `json:"status"`
	ID     pgtype.UUID         `json:"id"`
}

// sent_at é gravado só na primeira vez que o pedido sai do rascunho
func (q *Queries) UpdatePurchaseOrderStatus(ctx context.Context, arg UpdatePurchaseOrderStatusParams) error {
	_, err := q.db.Exec(ctx, updatePurchaseOrderStatus, arg.Status, arg.ID)
	return err
}
